<script setup>
import {computed,onMounted,onBeforeUnmount,reactive,ref} from 'vue'
import Icon from './components/Icon.vue'
import ModelSelect from './components/ModelSelect.vue'
import DreamerPatient from './components/DreamerPatient.vue'
import DreamerBatch from './components/DreamerBatch.vue'
import DreamerLearning from './components/DreamerLearning.vue'
import {request,post,downloadDreamerJob} from './api'
import {phaseLabels,statusLabels,terminalLabels,hours} from './dreamer-utils'
import './dreamer.css'

const page=ref('studio'),health=ref(null),source=ref(null),models=ref([]),cases=ref([]),totalCases=ref(0),offset=ref(0)
const selectedCase=ref(null),job=ref(null),history=ref([]),error=ref(''),notice=ref(''),busy=ref(false),sourceLoading=ref(true),batchId=ref(null)
const form=reactive({case_id:'',model:'Qwen3.8-27B',backend:'api',seed:42,max_operations:96,max_hours:168,policy_model:null,outcome_model:null,max_followups:null})
const running=computed(()=>['queued','running'].includes(job.value?.status))
const titles={learning:['模型训练与验证','查看真实来源标签、训练覆盖范围和独立测试误差。'],studio:['患者诊疗模拟工作台','从入院检查前的信息出发，让医生决策与患者响应形成连续病程。'],batch:['批量构建患者病程','每名患者独立决策、独立演化，支持三阶段病历与整批导出。'],history:['已保存的模拟记录','查看EHR Dreamer生成的病历。旧版任务保留在独立入口。']}
let timer,controller,token=0,disposed=false,noticeTimer,navigation=0
function stop(){clearTimeout(timer);controller?.abort();token++}
function remember(key,id){try{id?localStorage.setItem(key,id):localStorage.removeItem(key)}catch{}}
function select(c){if(!c)return;selectedCase.value=c;form.case_id=c.id}
async function loadCases(next=0){sourceLoading.value=true;try{const r=await request(`/dreamer/cases?offset=${next}&limit=12`);if(disposed)return;cases.value=r.items;totalCases.value=r.total;offset.value=next;if(!selectedCase.value&&r.items.length)select(r.items[0])}catch(e){error.value=e.message}finally{sourceLoading.value=false}}
async function refreshHistory(){const r=await request('/dreamer/generations');if(!disposed)history.value=r.items}
function apply(result){job.value=result;remember('ehrdreamer-job',result.id);if(result.batch_id)batchId.value=result.batch_id}
async function poll(id,generation){controller=new AbortController();try{const r=await request(`/dreamer/generations/${id}`,{signal:controller.signal});if(disposed||generation!==token)return;apply(r);if(['queued','running'].includes(r.status))timer=setTimeout(()=>poll(id,generation),1100);else refreshHistory().catch(()=>{})}catch(e){if(e.name!=='AbortError'&&!disposed&&generation===token){error.value='进度连接中断，正在重试。';timer=setTimeout(()=>poll(id,generation),2500)}}}
async function openJob(id,fromBatch=null){stop();const generation=token,navVersion=navigation;error.value='';try{const r=await request(`/dreamer/generations/${id}`);if(disposed||generation!==token||navVersion!==navigation)return;apply(r);Object.assign(form,r.request);selectedCase.value=r.case;batchId.value=fromBatch||r.batch_id||null;page.value='studio';window.scrollTo({top:0});if(['queued','running'].includes(r.status))poll(id,generation)}catch(e){error.value=e.message}}
function payload(){return {...form,source_sha256:source.value?.source_sha256}}
async function generate(){busy.value=true;error.value='';try{const r=await post('/dreamer/generations',payload());stop();apply(r);batchId.value=null;poll(r.id,token);await refreshHistory()}catch(e){error.value=e.message}finally{busy.value=false}}
async function retry(){if(!job.value)return;busy.value=true;error.value='';try{const r=await post(`/dreamer/generations/${job.value.id}/retry`,{});stop();apply(r);poll(r.id,token);await refreshHistory()}catch(e){error.value=e.message}finally{busy.value=false}}
async function exportJob(format){try{await downloadDreamerJob(job.value.id,format);notice.value='病历已导出';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.value='',3000)}catch(e){error.value=e.message}}
function fresh(){navigation++;stop();job.value=null;remember('ehrdreamer-job',null);page.value='studio';batchId.value=null;form.max_operations=96;error.value='';if(cases.value.length)select(cases.value[0]);window.scrollTo({top:0})}
function setBatch(id){batchId.value=id;remember('ehrdreamer-batch',id)}
function nav(p){navigation++;page.value=p;error.value='';window.scrollTo({top:0});if(p==='history')refreshHistory().catch(e=>error.value=e.message)}
onMounted(async()=>{
  const results=await Promise.allSettled([request('/dreamer/health'),request('/models'),request('/dreamer/source'),loadCases(),refreshHistory()])
  if(disposed)return
  if(results[0].status==='fulfilled')health.value=results[0].value
  if(results[1].status==='fulfilled')models.value=results[1].value.items
  if(results[2].status==='fulfilled')source.value=results[2].value
  else error.value=results[2].reason.message
  if(results[0].status==='rejected')error.value='后端服务暂不可用，请检查本地服务是否启动。'
  try{batchId.value=localStorage.getItem('ehrdreamer-batch');const saved=localStorage.getItem('ehrdreamer-job');if(saved&&navigation===0)await openJob(saved)}catch{}
})
onBeforeUnmount(()=>{disposed=true;stop();clearTimeout(noticeTimer)})
</script>
<template>
  <div class="dreamer-app">
    <aside class="ds-sidebar"><a class="ds-brand" href="/"><span><Icon name="pulse" :size="26"/></span><div>EHR <b>Dreamer</b><small>CLINICAL WORLD SIMULATOR</small></div></a><span class="ds-nav-caption">研究工作空间</span><nav aria-label="EHR Dreamer导航"><button :class="{active:page==='studio'}" @click="nav('studio')"><Icon name="grid"/>生成工作台</button><button :class="{active:page==='batch'}" @click="nav('batch')"><Icon name="layers"/>十人批次</button><button :class="{active:page==='learning'}" @click="nav('learning')"><Icon name="file"/>训练与验证</button><button :class="{active:page==='history'}" @click="nav('history')"><Icon name="clock"/>历史记录</button></nav><div class="ds-sidebar-info"><span class="ds-kicker">SEPARATED MODELS</span><p>医生策略</p><small>根据已知信息选择操作</small><p>患者环境</p><small>随时间与干预持续演化</small><p>结局文书</p><small>由状态与证据共同约束</small></div><a class="ds-legacy" href="/?legacy=1"><Icon name="book" :size="17"/>旧版 EHRWorld 任务<Icon name="chevron" :size="13"/></a></aside>
    <div class="ds-main"><header class="ds-topbar"><span>研究工作空间 <Icon name="chevron" :size="12"/> <strong>{{ page==='studio'?'生成工作台':page==='batch'?'十人批次':page==='learning'?'训练与验证':'历史记录' }}</strong></span><div><span class="ds-service" :class="{online:health}"><i></i>{{ health?'服务在线':'连接中' }}</span><a href="/docs" target="_blank" rel="noreferrer">API文档</a></div></header><nav class="ds-mobile-nav" aria-label="移动导航"><button :class="{active:page==='studio'}" @click="nav('studio')">工作台</button><button :class="{active:page==='batch'}" @click="nav('batch')">十人批次</button><button :class="{active:page==='learning'}" @click="nav('learning')"><Icon name="file"/>训练与验证</button><button :class="{active:page==='history'}" @click="nav('history')">历史记录</button><a href="/?legacy=1">旧版</a></nav><main class="ds-content">
      <div class="ds-page-heading"><div><span class="ds-kicker">EHR DREAMER · NEONATAL RESEARCH</span><h1>{{ titles[page][0] }}</h1><p>{{ titles[page][1] }}</p></div><button class="ds-button" @click="fresh"><Icon name="plus" :size="16"/>新建模拟</button></div>
      <div v-if="error" class="ds-alert" role="alert"><Icon name="warning" :size="18"/><span>{{ error }}</span><button @click="error=''" aria-label="关闭提示">×</button></div>
      <template v-if="page==='studio'">
        <button v-if="job?.batch_id" class="ds-button ds-back" @click="setBatch(job.batch_id);nav('batch')"><Icon name="arrow" :size="16"/>返回10人批次 · 患者 {{ job.batch_index }}</button>
        <div class="ds-studio-grid"><section class="ds-card ds-config"><div class="ds-panel-head"><div><h2>住院起点</h2><p>仅使用检查前可以知道的资料</p></div><Icon name="user"/></div><form @submit.prevent="generate"><fieldset :disabled="busy||running"><label class="ds-field">来源病例<select :value="form.case_id" @change="select(cases.find(c=>c.id===$event.target.value))"><option v-if="selectedCase&&!cases.some(c=>c.id===selectedCase.id)" :value="selectedCase.id">{{ selectedCase.label }} · {{ selectedCase.phenotype }}</option><option v-for="c in cases" :key="c.id" :value="c.id">{{ c.label }} · {{ c.phenotype }}</option></select></label><div class="ds-source-pager"><button type="button" :disabled="offset===0||sourceLoading" @click="loadCases(offset-12)">上一页</button><span>{{ offset+1 }}–{{ Math.min(offset+12,totalCases) }} / {{ totalCases }}</span><button type="button" :disabled="offset+12>=totalCases||sourceLoading" @click="loadCases(offset+12)">下一页</button></div><div v-if="selectedCase" class="ds-intake-preview"><strong>{{ selectedCase.intake.chief_complaint }}</strong><p>{{ selectedCase.intake.sex }} · {{ selectedCase.intake.gestational_weeks==null?'孕周待核实':selectedCase.intake.gestational_weeks+'周' }} · {{ selectedCase.intake.birth_weight_g==null?'出生体重待核实':selectedCase.intake.birth_weight_g+'g' }}</p><p>{{ selectedCase.intake.perinatal_risks.join('、')||'围产风险未可靠提取' }}</p><details><summary>来源质量提示</summary><p v-for="flag in selectedCase.quality_flags" :key="flag">{{ flag }}</p></details></div>
          <ModelSelect v-model="form.model" :models="models"/><p class="ds-note">患者动力学使用本地已训练模型；大模型选择作用于医生策略和结局文书。</p><label class="ds-field">生成模式<select v-model="form.backend"><option value="api">API医生与复合患者环境</option><option value="demo">离线闭环演示</option></select></label><div class="ds-field-row"><label class="ds-field">操作预算<select v-model.number="form.max_operations"><option v-for="n in [24,48,64,96,128,160]" :key="n" :value="n">{{ n }}次</option></select></label><label class="ds-field">随机种子<input v-model.number="form.seed" type="number" min="0" max="2147483647"/></label></div><label class="ds-field">模拟时间上限（小时）<input v-model.number="form.max_hours" type="number" min="6" max="720" step="6"/></label><label class="ds-field">针对性复评轮次上限<select v-model.number="form.max_followups"><option :value="null">按来源流程（默认2轮）</option><option v-for="n in [1,2,3,4]" :key="n" :value="n">{{ n }}轮</option></select></label><details class="ds-role-settings"><summary>分别配置大模型角色</summary><label v-for="(label,key) in {policy_model:'医生策略',outcome_model:'结局文书'}" :key="key" class="ds-field">{{ label }}<select v-model="form[key]"><option :value="null">沿用所选生成模型</option><option v-for="m in models" :key="m.id" :value="m.id">{{ m.name }}</option></select></label></details><p class="ds-note">预算用于限制模拟成本。到达预算会记录为未完成病程，不直接判定治愈出院。</p><button class="ds-button primary ds-generate" type="submit" :disabled="!health||!form.case_id||sourceLoading"><span v-if="busy||running" class="spinner"></span><Icon v-else name="spark" :size="17"/>{{ running?'正在模拟 '+job.operations+' 次操作':'开始患者模拟' }}<Icon v-if="!running" name="arrow" :size="16"/></button></fieldset></form></section>
          <div class="ds-results"><DreamerPatient v-if="job" :job="job" @export="exportJob" @retry="retry"/><section v-else class="ds-card ds-empty ds-welcome"><span class="ds-welcome-icon"><Icon name="layers" :size="32"/></span><span class="ds-kicker">FROM DECISION TO RESPONSE</span><h2>让病历沿着操作与反馈展开</h2><p>先检查、再判断，在治疗与复评中推进病程。<br/>每一步记录医生做了什么，以及患者何时出现可见响应。</p><div class="ds-stage-preview"><span v-for="(label,key) in phaseLabels" :key="key">{{ label }}</span></div><small>选择左侧来源病例与模型开始。离线演示也经过同一套环境执行与记录流程。</small></section></div>
        </div>
      </template>
      <DreamerBatch v-else-if="page==='batch'" :models="models" :initial-batch-id="batchId" :default-model="form.model" @open="openJob" @selected="setBatch" @updated="refreshHistory().catch(()=>{})"/>
      <DreamerLearning v-else-if="page==='learning'"/><section v-else class="ds-card ds-history"><div class="ds-panel-head"><h2>EHR Dreamer模拟记录</h2><button class="ds-button" @click="refreshHistory().catch(e=>error=e.message)">刷新</button></div><button v-for="item in history" :key="item.id" class="ds-history-row" @click="openJob(item.id)"><span class="ds-case-number"><Icon name="user" :size="17"/></span><div><strong>{{ item.case.label }}</strong><small>{{ item.case.phenotype }} · {{ item.request.backend==='demo'?'离线演示':item.models.policy.name }}</small></div><span>{{ hours(item.time_hours) }} · {{ item.operations }}操作</span><span class="ds-status" :class="item.status">{{ terminalLabels[item.terminal_status]||statusLabels[item.status] }}</span><Icon name="chevron" :size="16"/></button><div v-if="!history.length" class="ds-empty"><h3>尚无新架构记录</h3><p>旧版任务继续保存在旧版入口；新模拟会独立保存。</p></div></section>
      <section v-if="source" class="ds-card ds-source-overview"><details><summary><Icon name="file" :size="16"/>来源工作簿 · {{ source.records.toLocaleString() }}条 / {{ source.fields }}字段</summary><p>{{ source.source_file }}</p><p v-for="n in source.notes" :key="n">{{ n }}</p><div class="ds-table-scroll"><table class="ds-table"><thead><tr><th>来源字段</th><th>非空记录</th><th>用途</th></tr></thead><tbody><tr v-for="f in source.field_coverage" :key="f.name"><td>{{ f.name }}</td><td>{{ f.nonempty }}</td><td>{{ f.usage }}</td></tr></tbody></table></div></details></section>
      <footer class="ds-footer"><span><Icon name="pulse" :size="14"/>EHR Dreamer · 策略与患者环境分离</span><span>合成研究数据 · 统一住院病历结构</span></footer>
    </main></div><div v-if="notice" class="ds-toast" role="status">{{ notice }}</div>
  </div>
</template>
